# Agent unattended board accept for vgpoint (COM3).
# Same flow as vgpoint_host_apply.ps1, but continues after test without Read-Host.
param(
  [string]$ComPort = "COM3",
  [int]$Baud = 115200,
  [string]$PointsFile = ""
)

$ErrorActionPreference = "Stop"
$script:pass = 0
$script:fail = 0

if ($PointsFile -eq "") {
  $PointsFile = Join-Path $PSScriptRoot "vgpoint_demo_points.json"
}

function Wait-Prompt {
  param([string]$Buf, [int]$TimeoutSec = 12)
  $deadline = (Get-Date).AddSeconds($TimeoutSec)
  while ((Get-Date) -lt $deadline) {
    if ($Buf -match "nsh>") { return $true }
    Start-Sleep -Milliseconds 120
  }
  return $false
}

function Send-Serial {
  param(
    [System.IO.Ports.SerialPort]$Port,
    [string]$Cmd,
    [int]$WaitSec = 20
  )
  $Port.DiscardInBuffer()
  $Port.WriteLine($Cmd)
  Start-Sleep -Milliseconds 400
  $buf = ""
  $deadline = (Get-Date).AddSeconds($WaitSec)
  while ((Get-Date) -lt $deadline) {
    if ($Port.BytesToRead -gt 0) { $buf += $Port.ReadExisting() }
    if (Wait-Prompt $buf 1) { break }
    Start-Sleep -Milliseconds 120
  }
  Write-Output "`n=== $Cmd ===`n$buf"
  return @{ Text = $buf }
}

function Assert-Match {
  param([string]$Name, [string]$Hay, [string]$Pattern)
  if ($Hay -match $Pattern) {
    Write-Output "[PASS] $Name"
    $script:pass++
  } else {
    Write-Output "[FAIL] $Name (pattern: $Pattern)"
    Write-Output "---- haystack ----"
    Write-Output $Hay
    $script:fail++
  }
}

function Build-AddCmd {
  param($pt)
  $tag = [string]$pt.tag
  $addr = [int]$pt.addr
  $reg = [int]$pt.reg
  $cmd = "vgpoint add -t $tag -a $addr -r $reg"
  if ($null -ne $pt.fc) { $cmd += " -f $([int]$pt.fc)" }
  if ($null -ne $pt.qty) { $cmd += " -q $([int]$pt.qty)" }
  if ($null -ne $pt.dtype -and "$($pt.dtype)" -ne "") { $cmd += " -d $($pt.dtype)" }
  if ($null -ne $pt.scale) { $cmd += " -s $($pt.scale)" }
  if ($null -ne $pt.unit -and "$($pt.unit)" -ne "") { $cmd += " -u $($pt.unit)" }
  if ($null -ne $pt.cmp -and "$($pt.cmp)" -ne "") { $cmd += " -k $($pt.cmp)" }
  if ($null -ne $pt.warn) { $cmd += " -w $($pt.warn)" }
  if ($null -ne $pt.crit) { $cmd += " -C $($pt.crit)" }
  if ($null -ne $pt.fail_n) { $cmd += " -n $([int]$pt.fail_n)" }
  if ($cmd.Length -gt 120) {
    throw "command longer than 120 bytes: $cmd"
  }
  return $cmd
}

if (-not (Test-Path $PointsFile)) {
  throw "points file not found: $PointsFile"
}

$json = Get-Content -Raw -Path $PointsFile | ConvertFrom-Json
$points = @()
if ($null -ne $json.points) { $points = @($json.points) }
elseif ($json -is [System.Array]) { $points = @($json) }
if ($points.Count -lt 1) {
  throw "no points in $PointsFile"
}

$port = New-Object System.IO.Ports.SerialPort
$port.PortName = $ComPort
$port.BaudRate = $Baud
$port.ReadTimeout = 8000
$port.NewLine = "`n"

try {
  $port.Open()
  Start-Sleep -Seconds 5
  $boot = ""
  $bootDeadline = (Get-Date).AddSeconds(25)
  while ((Get-Date) -lt $bootDeadline) {
    if ($port.BytesToRead -gt 0) { $boot += $port.ReadExisting() }
    if ($boot -match "nsh>") { break }
    Start-Sleep -Milliseconds 200
  }
  if ($boot -notmatch "nsh>") {
    $boot += (Send-Serial $port "" 8).Text
  }
  Assert-Match "nsh prompt" $boot "nsh>"
  while ($port.BytesToRead -gt 0) { [void]$port.ReadExisting(); Start-Sleep -Milliseconds 50 }

  $r = Send-Serial $port "?" 8
  Assert-Match "vgpoint in help" $r.Text "vgpoint"

  $r = Send-Serial $port "vgpoint apply" 8
  Assert-Match "apply need_confirm" $r.Text "vgpoint: ERR cmd=apply code=need_confirm"

  $r = Send-Serial $port "vgpoint list" 12
  Assert-Match "list committed before write" $r.Text "vgpoint: OK cmd=list table=committed"

  foreach ($pt in $points) {
    $add = Build-AddCmd $pt
    $r = Send-Serial $port $add 12
    if ($r.Text -match "code=dup_tag") {
      $set = ($add -replace "^vgpoint add -t $($pt.tag) ", "vgpoint set $($pt.tag) ")
      $r = Send-Serial $port $set 12
      Assert-Match "set $($pt.tag)" $r.Text "vgpoint: OK cmd=set"
    } else {
      Assert-Match "add $($pt.tag)" $r.Text "vgpoint: OK cmd=add"
    }
  }

  $r = Send-Serial $port "vgpoint list" 12
  Assert-Match "list still committed after add" $r.Text "vgpoint: OK cmd=list table=committed"

  $r = Send-Serial $port "vgpoint list -c" 12
  Assert-Match "candidate has temp" $r.Text "vgpoint: POINT tag=temp"
  Assert-Match "candidate has flood" $r.Text "vgpoint: POINT tag=flood"

  $r = Send-Serial $port "vgpoint test" 45
  Assert-Match "test READ or fail token" $r.Text "vgpoint: READ |code=test_fail|code=no_candidate|code=bus_busy|code=io"
  Write-Output "---- test body ----"
  Write-Output $r.Text

  Write-Output "Agent continue: vgpoint apply --confirm"

  $r = Send-Serial $port "vgpoint apply --confirm" 15
  Assert-Match "apply confirm" $r.Text "vgpoint: OK cmd=apply table=committed"

  $r = Send-Serial $port "vgpoint list" 12
  Assert-Match "list committed after apply" $r.Text "vgpoint: OK cmd=list table=committed"
  Assert-Match "committed POINT temp" $r.Text "vgpoint: POINT tag=temp"
  Assert-Match "committed POINT flood" $r.Text "vgpoint: POINT tag=flood"

  $r = Send-Serial $port "cat /data/velaguard/config/points.json" 8
  Assert-Match "points.json has temp" $r.Text '"tag":"temp"'
  Assert-Match "points.json has flood" $r.Text '"tag":"flood"'

  Write-Output "`n[vgpoint_agent_accept] pass=$($script:pass) fail=$($script:fail)"
  if ($script:fail -gt 0) { exit 1 }
}
catch {
  Write-Error "vgpoint_agent_accept failed: $($_.Exception.Message)"
  exit 1
}
finally {
  if ($port.IsOpen) { $port.Close() }
}
